"""Performance catalog: one view over every artifact the show can put on screen.

Sources (no duplicated metadata):
* the matcher collection (`data/artworks/annotations.yaml`, 24 paintings),
* extra early artifacts in `data/performance/records.yaml`, generated by
  `itu show catalog build` from the museum APIs (rights checked by `fetch_record`),
* approved memes (`data/memes/annotations/*.json`, reference-only images).

`data/performance/catalog.yaml` adds only performance fields: chapter, description,
pose tags, and — for a few curated pictures — what a participant may imitate.
"""

from __future__ import annotations

import logging
import random
from dataclasses import dataclass, field
from pathlib import Path

import httpx
import yaml

from .script import ALL_CHAPTERS, SPECIAL_SHOWS, Script

log = logging.getLogger(__name__)

SUBJECTS = ("human_and_dog", "dog_only", "human_only")
CANINE = ("certain", "possible")
POSTURES = ("sitting", "standing")
# presentation rounds: what the person in the picture does, and what the robot can do to echo the dog
HUMAN_POSES = ("sitting", "standing", "kneeling", "lying", "riding")  # riding: a person on a horse — no visitor pose matches it
DOG_SIDES = ("left", "right", "front")
OPEN_RIGHTS = ("Public Domain", "CC0")
RECORDS_FILE = "records.yaml"
CATALOG_FILE = "catalog.yaml"


@dataclass(frozen=True)
class InteractiveSpec:
    pose_subject: str  # "human" | "dog"
    safe_to_imitate: bool
    request: str
    posture: str
    head_tilt: bool = False
    suggest: tuple[str, ...] = ()
    priority: int = 9
    crop: tuple[float, float, float, float] | None = None
    note: str = ""
    robot_side: str = ""  # where the dog is in the picture, as the viewer sees it: left | right | front
    robot_note: str = ""  # how the operator places the robot for the photo
    robot_behavior: str = ""  # the pose the robot takes there (RobotBehavior value), e.g. sit

    def placement(self) -> str:
        """One line for the operator: where to put the robot before the person poses."""
        if not self.robot_side:
            return ""
        where = {"left": "on the LEFT of the person", "right": "on the RIGHT of the person",
                 "front": "IN FRONT of the person, low"}.get(self.robot_side, self.robot_side)
        return f"Place the robot {where} (as seen on the screen). {self.robot_note}".strip()

    @property
    def semantic_only(self) -> bool:
        """Dog poses are compared by meaning (sitting, upright…), never by skeleton."""
        return self.pose_subject != "human"


@dataclass
class ShowArtifact:
    id: str
    kind: str  # "art" | "meme"
    title: str
    artist: str
    date: str
    museum: str
    page_url: str
    rights_status: str
    rights_statement: str
    image_path: Path | None
    chapter: str
    subject: str
    canine: str
    description: str
    pose_tags: tuple[str, ...] = ()
    interactive: InteractiveSpec | None = None
    extra: dict = field(default_factory=dict)
    human: str = ""  # the main person's posture (sitting | standing | kneeling | lying) — for the rounds
    dog: str = ""  # a RobotBehavior that echoes the painted dog (sit, lie_down, stand, greet, stretch)
    dog_side: str = ""  # where the dog is next to the person, as the viewer sees it (left | right | front)
    in_rounds: bool = True  # false: shown in the story only — no visible dog/pose to answer in a round
    dog_facing: str = ""  # which way the painted dog looks, as the viewer sees it (viewer | left | right | person | away)

    @property
    def displayable(self) -> bool:
        return self.image_path is not None and self.image_path.exists()

    def label_lines(self) -> list[str]:
        meta = self.artist + (f", {self.date}" if self.date else "")
        return [self.title, meta, f"{self.museum} · {self.rights_status}"]

    def facts(self) -> dict:
        """Structured facts for a voice model: verified metadata only."""
        return {"title": self.title, "artist": self.artist, "date": self.date, "museum": self.museum,
                "description": self.description, "visible": list(self.pose_tags),
                "animal_identification": self.canine}


class CatalogError(ValueError):
    pass


def _spec(raw: dict | None) -> InteractiveSpec | None:
    if not raw:
        return None
    crop = raw.get("crop")
    return InteractiveSpec(
        pose_subject=str(raw.get("pose_subject", "")), safe_to_imitate=bool(raw.get("safe_to_imitate", False)),
        request=str(raw.get("request", "")).strip(), posture=str(raw.get("posture", "")),
        head_tilt=bool(raw.get("head_tilt", False)), suggest=tuple(raw.get("suggest") or ()),
        priority=int(raw.get("priority", 9)), crop=tuple(float(v) for v in crop) if crop else None,
        note=str(raw.get("note", "")).strip(),
        robot_side=str((raw.get("robot_spot") or {}).get("side", "")).strip(),
        robot_note=str((raw.get("robot_spot") or {}).get("note", "")).strip(),
        robot_behavior=str((raw.get("robot_spot") or {}).get("behavior", "")).strip(),
    )


class PerformanceCatalog:
    def __init__(self, data_dir: Path, art_repo, meme_repo=None):
        self.data_dir = Path(data_dir)
        self.art_repo = art_repo
        self.meme_repo = meme_repo
        self.image_dir = self.data_dir / "images"
        raw = yaml.safe_load((self.data_dir / CATALOG_FILE).read_text(encoding="utf-8")) or {}
        self.raw: dict = raw.get("artifacts") or {}
        rec_path = self.data_dir / RECORDS_FILE
        self.records: dict = (yaml.safe_load(rec_path.read_text(encoding="utf-8")) or {}).get("records", {}) \
            if rec_path.exists() else {}
        self.items: dict[str, ShowArtifact] = {}
        self.missing: dict[str, str] = {}
        for key, entry in self.raw.items():
            try:
                self.items[key] = self._build(key, entry or {})
            except CatalogError as exc:
                self.missing[key] = str(exc)

    # ------------------------------------------------------------------ assembly
    def image_path_for(self, key: str) -> Path:
        return self.image_dir / f"{key.replace(':', '_')}.jpg"

    def _build(self, key: str, e: dict) -> ShowArtifact:
        common = dict(chapter=str(e.get("chapter", "")), subject=str(e.get("subject", "")),
                      canine=str(e.get("canine", "certain")), description=str(e.get("description", "")).strip(),
                      pose_tags=tuple(e.get("pose_tags") or ()), interactive=_spec(e.get("interactive")),
                      human=str(e.get("human", "") or ""), dog=str(e.get("dog", "") or ""),
                      dog_side=str(e.get("dog_side", "") or ""), dog_facing=str(e.get("dog_facing", "") or ""),
                      in_rounds=bool(e.get("in_rounds", True)))
        if key.startswith("meme:"):
            meme = self.meme_repo.get(key) if self.meme_repo else None
            if meme is None:
                raise CatalogError("meme not found among approved memes")
            img = self.meme_repo.local_image(meme)
            return ShowArtifact(id=key, kind="meme", title=meme.name, artist=meme.attribution, date=meme.year,
                                museum="Internet culture", page_url=str(meme.page_url),
                                rights_status="reference only — image not reproduced",
                                rights_statement=meme.image.rights.value, image_path=img,
                                extra={"subject": meme.subject}, **common)
        if e.get("fetch"):
            rec = self.records.get(key)
            if not rec:
                raise CatalogError("no museum record yet — run `itu show catalog build`")
            return ShowArtifact(id=key, kind="art", title=rec["title"], artist=rec["artist"], date=rec["date"],
                                museum=rec["museum"], page_url=rec["page_url"], rights_status=rec["rights_status"],
                                rights_statement=rec["rights_statement"], image_path=self.image_path_for(key),
                                extra={"verified_on": rec.get("verified_on", "")}, **common)
        art = self.art_repo.get(key) if self.art_repo else None
        if art is None:
            raise CatalogError("not in the artwork collection (data/artworks/annotations.yaml)")
        return ShowArtifact(id=key, kind="art", title=art.title, artist=art.artist, date=art.date, museum=art.museum,
                            page_url=str(art.page_url), rights_status=art.rights.status,
                            rights_statement=art.rights.source_statement, image_path=self.art_repo.local_image(art),
                            **common)

    # ------------------------------------------------------------------ queries
    def get(self, key: str) -> ShowArtifact | None:
        return self.items.get(key)

    def artifact_for_scene(self, scene_id: str) -> ShowArtifact | None:
        """Any matchable painting or meme as a ShowArtifact (catalogued ones keep their show metadata)."""
        if scene_id in self.items:
            return self.items[scene_id]
        entry = {"chapter": "invitation", "subject": "human_and_dog", "canine": "certain", "description": ""}
        try:
            return self._build(scene_id, entry)
        except CatalogError:
            return None

    def for_chapter(self, chapter: str) -> list[ShowArtifact]:
        return [a for a in self.items.values() if a.chapter == chapter]

    def interactive(self, preference: str = "any") -> list[ShowArtifact]:
        """Curated, safe, displayable pictures a participant may imitate, best first."""
        out = [a for a in self.items.values()
               if a.interactive and a.interactive.safe_to_imitate and a.displayable]
        if preference in POSTURES:
            out = [a for a in out if a.interactive.posture == preference] or out
        return sorted(out, key=lambda a: (a.interactive.priority, a.id))

    def choose_interactive(self, preference: str = "sitting", *, exclude: set[str] | None = None,
                           rng: random.Random | None = None, prefer_human: bool = True) -> ShowArtifact | None:
        cands = self.interactive(preference)
        if prefer_human:
            cands = [a for a in cands if a.interactive.pose_subject == "human"] or cands
        fresh = [a for a in cands if a.id not in (exclude or set())] or cands
        if not fresh:
            return None
        best = fresh[0].interactive.priority
        top = [a for a in fresh if a.interactive.priority == best]
        return (rng or random).choice(top) if len(top) > 1 else top[0]

    # ------------------------------------------------------------------ validation
    def validate(self, script: Script | None = None, pose_lines: set[str] | None = None) -> list[str]:
        problems = [f"{k}: {why}" for k, why in self.missing.items()]
        for a in self.items.values():
            p = f"{a.id}:"
            if a.chapter not in ALL_CHAPTERS:
                problems.append(f"{p} unknown chapter {a.chapter!r}")
            if a.subject not in SUBJECTS:
                problems.append(f"{p} subject must be one of {SUBJECTS}")
            if a.canine not in CANINE:
                problems.append(f"{p} canine must be one of {CANINE}")
            if not a.description:
                problems.append(f"{p} needs a description")
            if a.human and a.human not in HUMAN_POSES:
                problems.append(f"{p} human must be one of {HUMAN_POSES}")
            if a.dog_side and a.dog_side not in DOG_SIDES:
                problems.append(f"{p} dog_side must be one of {DOG_SIDES}")
            if a.dog:
                from ..domain import RobotBehavior

                if a.dog not in {b.value for b in RobotBehavior}:
                    problems.append(f"{p} dog {a.dog!r} is not a RobotBehavior")
            if a.kind == "art":
                if a.rights_status not in OPEN_RIGHTS:
                    problems.append(f"{p} rights {a.rights_status!r} are not open access")
                if not a.displayable:
                    problems.append(f"{p} image file missing (run `itu show catalog build` / `itu artworks cache`)")
            s = a.interactive
            if s is None:
                continue
            if s.pose_subject not in ("human", "dog"):
                problems.append(f"{p} interactive.pose_subject must be human or dog")
            if a.subject == "dog_only" and s.pose_subject == "human":
                problems.append(f"{p} a dog-only picture cannot have a human target pose")
            if a.subject == "human_only" and s.pose_subject == "dog":
                problems.append(f"{p} a human-only picture cannot have a dog target pose")
            if s.posture not in POSTURES:
                problems.append(f"{p} interactive.posture must be one of {POSTURES}")
            if not s.request:
                problems.append(f"{p} interactive.request is empty")
            if s.robot_side and s.robot_side not in ("left", "right", "front"):
                problems.append(f"{p} interactive.robot_spot.side must be left, right or front")
            if s.robot_behavior:
                from ..domain import RobotBehavior

                if s.robot_behavior not in {b.value for b in RobotBehavior}:
                    problems.append(f"{p} interactive.robot_spot.behavior {s.robot_behavior!r} is not a RobotBehavior")
            if a.kind != "art":
                problems.append(f"{p} only open-access artworks can be interactive")
            if s.crop is not None and not (len(s.crop) == 4 and 0 <= s.crop[0] < s.crop[2] <= 1
                                           and 0 <= s.crop[1] < s.crop[3] <= 1):
                problems.append(f"{p} interactive.crop must be [x0, y0, x1, y1] within 0..1")
            if pose_lines is not None:
                for key in s.suggest:
                    if key not in pose_lines:
                        problems.append(f"{p} suggestion {key!r} has no line in lines.<lang>.yaml → pose")
        if script is not None:
            for sid in sorted(script.shown_ids()):
                a = self.items.get(sid)
                if a is None:
                    problems.append(f"script shows {sid}, which is not in the catalog")
            for ch in script.chapters:
                for c in ch.cues:
                    if c.show and c.show not in SPECIAL_SHOWS and c.show in self.items:
                        if self.items[c.show].chapter != ch.id and ch.id not in ("invitation", "present", "last_dog", "rescue"):
                            problems.append(f"{c.id} shows {c.show}, catalogued for chapter "
                                            f"{self.items[c.show].chapter!r}")
        if not self.interactive():
            problems.append("no interactive picture is available (needs safe_to_imitate and a local image)")
        return problems


# ---------------------------------------------------------------------- building records
def build_records(data_dir: Path, *, fetch=None, http: httpx.Client | None = None, refresh: bool = False) -> list[str]:
    """Fetch museum metadata for `fetch: true` entries, verify rights, cache images.

    `fetch` defaults to `museum_clients.fetch_record` (raises RightsError if not open).
    """
    from ..artworks.museum_clients import USER_AGENT, RightsError, fetch_record

    data_dir = Path(data_dir)
    fetch = fetch or fetch_record
    raw = (yaml.safe_load((data_dir / CATALOG_FILE).read_text(encoding="utf-8")) or {}).get("artifacts") or {}
    rec_path = data_dir / RECORDS_FILE
    records = (yaml.safe_load(rec_path.read_text(encoding="utf-8")) or {}).get("records", {}) if rec_path.exists() else {}
    img_dir = data_dir / "images"
    img_dir.mkdir(parents=True, exist_ok=True)
    http = http or httpx.Client(timeout=60, headers={"User-Agent": USER_AGENT}, follow_redirects=True)
    log_lines = []
    for key, entry in raw.items():
        if not (entry or {}).get("fetch"):
            continue
        img = img_dir / f"{key.replace(':', '_')}.jpg"
        if key in records and img.exists() and not refresh:
            log_lines.append(f"ok      {key}")
            continue
        try:
            r = fetch(key)
        except RightsError as exc:
            records.pop(key, None)
            log_lines.append(f"REFUSED {key}: {exc}")
            continue
        except Exception as exc:  # network etc.: keep what we have
            log_lines.append(f"FAILED  {key}: {exc}")
            continue
        records[key] = {"museum": r.museum, "museum_object_id": r.museum_object_id, "title": r.title,
                        "artist": r.artist, "date": r.date, "image_url": r.image_url, "page_url": r.page_url,
                        "rights_status": r.rights_status, "rights_statement": r.rights_statement,
                        "verified_on": r.verified_on, "classification": r.classification}
        try:
            resp = http.get(r.image_url)
            resp.raise_for_status()
            img.write_bytes(resp.content)
            log_lines.append(f"fetched {key}: {r.title} ({r.date}) — {r.rights_status}")
        except Exception as exc:
            log_lines.append(f"IMAGE?  {key}: {exc}")
    header = ("# GENERATED by `itu show catalog build` from the museum APIs (rights verified per record).\n"
              "# Do not edit by hand; edit catalog.yaml and rebuild.\n")
    rec_path.write_text(header + yaml.safe_dump({"version": 1, "records": records}, sort_keys=True,
                                                allow_unicode=True, width=110), encoding="utf-8")
    return log_lines
